package com.eonmux.excalibur.filter.lsh;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

/**
 * Generates probing sequences for multi-probe LSH.
 *
 * <h2>Overview</h2>
 * <p>Multi-probe LSH improves recall by checking not just the exact hash bucket,
 * but also nearby buckets that are likely to contain similar vectors. This class
 * generates a sequence of hash perturbations ordered by their likelihood of
 * containing similar vectors.</p>
 *
 * <h2>Algorithm</h2>
 * <p>The probing sequence is generated by:</p>
 * <ol>
 *   <li>For each bit position, calculate the "distance" (how close the dot product
 *       was to zero - smaller means more uncertain)</li>
 *   <li>Generate perturbation vectors by flipping bits, ordered by total distance</li>
 *   <li>Prioritize flipping lower-order bits (more likely to be similar)</li>
 * </ol>
 *
 * <h2>Domain Correctness</h2>
 * <ul>
 *   <li><strong>Perturbation ordering</strong>: Based on the insight that bits with
 *       smaller margin (dot product closer to 0) are more likely to be incorrect</li>
 *   <li><strong>Sequence length</strong>: Limited by 2^numBits (all possible perturbations)</li>
 *   <li><strong>Hash values</strong>: Always non-negative (bit 63 never set)</li>
 * </ul>
 *
 * <h2>Thread Safety</h2>
 * <p>This class is thread-safe for read operations.</p>
 *
 * @author ExcaliburDB
 */
public class MultiProbeGenerator {

    /** Number of bits in the hash. */
    private final int numBits;

    /**
     * Creates a new MultiProbeGenerator for hashes with the specified number of bits.
     *
     * @param numBits Number of bits in the hash (1-63)
     * @throws IllegalArgumentException if numBits is out of range
     */
    public MultiProbeGenerator(int numBits) {
        if (numBits < 1 || numBits > 63) {
            throw new IllegalArgumentException(
                "numBits must be in range [1, 63], got: " + numBits);
        }
        this.numBits = numBits;
    }

    /**
     * Generates a probing sequence starting from the base hash.
     * Returns hashes ordered by likelihood of containing similar vectors.
     *
     * <p>The sequence includes:</p>
     * <ol>
     *   <li>The base hash (no perturbation)</li>
     *   <li>Single-bit flips (ordered by bit position, lower bits first)</li>
     *   <li>Two-bit flips (combinations of single-bit flips)</li>
     *   <li>And so on, up to the requested number of probes</li>
     * </ol>
     *
     * @param baseHash  The base hash value
     * @param numProbes The number of probe hashes to generate (including base)
     * @return List of hash values to probe, ordered by likelihood
     */
    public List<Long> generateProbingSequence(long baseHash, int numProbes) {
        if (numProbes < 1) {
            throw new IllegalArgumentException("numProbes must be >= 1, got: " + numProbes);
        }

        List<Long> probes = new ArrayList<>(numProbes);

        // Always include the base hash
        probes.add(baseHash);
        if (numProbes == 1) {
            return probes;
        }

        // Generate perturbation sequence using heap-based approach
        // Each entry is [bitmask, last_flipped_bit]
        PriorityQueue<long[]> heap = new PriorityQueue<>(
            Comparator.comparingLong(a -> a[0]));

        // Initialize with single-bit perturbations
        // Bit i has "distance" 2^i (lower bits = smaller distance = higher priority)
        for (int i = 0; i < numBits; i++) {
            long mask = 1L << i;
            heap.offer(new long[]{mask, i});
        }

        // Generate probes by extracting minimum distance perturbations
        while (probes.size() < numProbes && !heap.isEmpty()) {
            long[] entry = heap.poll();
            long mask = entry[0];
            int lastBit = (int) entry[1];

            long perturbedHash = baseHash ^ mask;
            probes.add(perturbedHash);

            // Generate next level perturbations (add one more bit flip)
            // Only flip bits higher than lastBit to avoid duplicates
            for (int i = lastBit + 1; i < numBits; i++) {
                long newMask = mask | (1L << i);
                heap.offer(new long[]{newMask, i});
            }
        }

        return probes;
    }

    /**
     * Generates a probing sequence with distance-based ordering.
     * This variant considers the margin of each bit decision.
     *
     * <p>When the dot product for a bit is close to zero, that bit is more
     * likely to be incorrect. This method takes an array of margins where
     * lower values indicate higher uncertainty.</p>
     *
     * @param baseHash The base hash value
     * @param margins  Array of margin values (one per bit), smaller = more uncertain
     * @param numProbes The number of probe hashes to generate
     * @return List of hash values to probe, ordered by likelihood
     */
    public List<Long> generateProbingSequenceWithMargins(long baseHash, float[] margins, int numProbes) {
        if (margins == null || margins.length != numBits) {
            throw new IllegalArgumentException(
                "margins must have length " + numBits + ", got " +
                (margins == null ? "null" : margins.length));
        }
        if (numProbes < 1) {
            throw new IllegalArgumentException("numProbes must be >= 1");
        }

        List<Long> probes = new ArrayList<>(numProbes);
        probes.add(baseHash);
        if (numProbes == 1) {
            return probes;
        }

        // Sort bits by margin (ascending - smaller margin = higher priority)
        int[] bitOrder = new int[numBits];
        for (int i = 0; i < numBits; i++) {
            bitOrder[i] = i;
        }

        // Sort by margin value
        for (int i = 0; i < numBits - 1; i++) {
            for (int j = i + 1; j < numBits; j++) {
                if (margins[bitOrder[j]] < margins[bitOrder[i]]) {
                    int tmp = bitOrder[i];
                    bitOrder[i] = bitOrder[j];
                    bitOrder[j] = tmp;
                }
            }
        }

        // Use heap-based perturbation generation
        PriorityQueue<Perturbation> heap = new PriorityQueue<>(
            Comparator.comparingDouble(Perturbation::totalMargin));

        // Initialize with single-bit perturbations
        for (int i = 0; i < numBits; i++) {
            int bit = bitOrder[i];
            heap.offer(new Perturbation(1L << bit, i, Math.abs(margins[bit])));
        }

        // Generate probes
        while (probes.size() < numProbes && !heap.isEmpty()) {
            Perturbation p = heap.poll();
            long perturbedHash = baseHash ^ p.mask;
            probes.add(perturbedHash);

            // Extend with higher-priority bits
            for (int i = p.lastBitIndex + 1; i < numBits; i++) {
                int bit = bitOrder[i];
                long newMask = p.mask | (1L << bit);
                heap.offer(new Perturbation(newMask, i, p.totalMargin + Math.abs(margins[bit])));
            }
        }

        return probes;
    }

    /**
     * Generates all possible single-bit perturbations.
     *
     * @param baseHash The base hash value
     * @return List of hashes with exactly one bit flipped
     */
    public List<Long> generateSingleBitPerturbations(long baseHash) {
        List<Long> perturbations = new ArrayList<>(numBits);
        for (int i = 0; i < numBits; i++) {
            perturbations.add(baseHash ^ (1L << i));
        }
        return perturbations;
    }

    /**
     * Generates the Hamming distance between two hashes.
     *
     * @param hash1 First hash
     * @param hash2 Second hash
     * @return The Hamming distance
     */
    public int hammingDistance(long hash1, long hash2) {
        return Long.bitCount(hash1 ^ hash2);
    }

    /**
     * Returns the number of bits in hashes handled by this generator.
     *
     * @return The number of bits
     */
    public int numBits() {
        return numBits;
    }

    /**
     * Calculates the maximum number of unique probes possible.
     * This is limited by 2^numBits (all possible bit combinations).
     *
     * @return The maximum number of unique probes
     */
    public long maxProbes() {
        return 1L << numBits;
    }

    /**
     * Helper class for margin-based perturbation tracking.
     */
    private static final class Perturbation {
        final long mask;
        final int lastBitIndex;
        final double totalMargin;

        Perturbation(long mask, int lastBitIndex, double totalMargin) {
            this.mask = mask;
            this.lastBitIndex = lastBitIndex;
            this.totalMargin = totalMargin;
        }

        double totalMargin() {
            return totalMargin;
        }
    }

    @Override
    public String toString() {
        return String.format("MultiProbeGenerator[numBits=%d]", numBits);
    }
}
